// loft: a thin loft 1 mm thick between a square and a smaller square, its ends trimmed to the profiles' planes
export function c008(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(-10, -10) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s2, "rect1", { "firstCorner" : vector(-5, -5) * millimeter, "secondCorner" : vector(5, 5) * millimeter });
    skSolve(s2);
    loft(context, id + "loft1", { "bodyType" : ExtendedToolBodyType.THIN, "operationType" : NewBodyOperationType.NEW, "wireProfilesArray" : [{ "wireProfileEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }, { "wireProfileEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }], "midplane" : false, "thickness1" : 1 * millimeter, "flipWall" : false, "thickness2" : 0 * millimeter, "trimEnds" : true });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)) };
}
